insert into public.areas (id, name_en, name_ru, highlights_en, highlights_ru, has_metro, price_psf, service_charge_psf, growth_pct, price_change_pct, source, updated_at) values
  ('downtown', 'Downtown Dubai', 'Даунтаун Дубай', array['Burj Khalifa/Dubai Mall metro station (Red Line), walkway from the mall','By car: DXB airport ~33 min, Palm Jumeirah ~21 min, JBR ~26 min','Dubai Mall (1,200 shops), Dubai Fountain, Dubai Opera, 11-hectare Burj Park','Schools: Citizens School, City Walk (1.6 km); 12 nearby schools rated Very Good or Outstanding'], array['Станция метро Burj Khalifa/Dubai Mall (красная ветка), переход из молла','На машине: аэропорт DXB ~33 мин, Палм ~21 мин, JBR ~26 мин','Dubai Mall (1 200 магазинов), Dubai Fountain, Dubai Opera, парк Burj Park 11 га','Школы: Citizens School в City Walk (1,6 км); рядом 12 школ с рейтингом Very Good или Outstanding'], true, 2674, 22, -0.5, -0.6, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: RERA index range 17–40, typical 18–25', '2026-11-02'),
  ('business-bay', 'Business Bay', 'Бизнес-Бэй', array['Business Bay metro station (Red Line); water buses on Dubai Canal','By car: Dubai Mall ~9 min, DXB airport ~32 min, Palm Jumeirah ~21 min, JBR ~25 min','Burj Khalifa about 1.5 km away; Downtown within walking distance','1,000+ shops, cafés and restaurants inside the community'], array['Станция метро Business Bay (красная ветка); водные автобусы по Dubai Canal','На машине: Dubai Mall ~9 мин, аэропорт DXB ~32 мин, Палм ~21 мин, JBR ~25 мин','Бурдж-Халифа примерно в 1,5 км, до Даунтауна можно дойти пешком','Более 1 000 магазинов, кафе и ресторанов в районе'], true, 2023, 15, 3.0, 6.9, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: RERA index community average ~14.75', '2026-11-02'),
  ('dubai-marina', 'Dubai Marina', 'Дубай Марина', array['Two Red Line metro stations plus Dubai Tram: a car is optional','By car: JBR ~5 min, Palm Jumeirah ~12 min, Dubai Mall ~20 min, DXB airport ~45 min','Marina Walk promenade, Dubai Marina Mall with cinema, Marina Beach 0.6 km','Schools: Emirates International School Meadows (2.4 km); 8 nearby schools rated Very Good or Outstanding'], array['Две станции красной ветки метро и трамвай: можно жить без машины','На машине: JBR ~5 мин, Палм ~12 мин, Dubai Mall ~20 мин, аэропорт DXB ~45 мин','Набережная Marina Walk, Dubai Marina Mall с кинотеатром, пляж в 600 м','Школы: Emirates International School Meadows (2,4 км); рядом 8 школ с рейтингом Very Good или Outstanding'], true, 2021, 16, 3.0, 4.7, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: RERA index community average ~16.1', '2026-11-02'),
  ('jbr', 'Jumeirah Beach Residence (JBR)', 'Джумейра Бич Резиденс (JBR)', array['Direct beach access and The Walk','Dubai Tram; Marina metro stations nearby','Strong holiday-home demand'], array['Прямой выход к пляжу и The Walk','Трамвай, станции метро Марины рядом','Высокий спрос на краткосрочную аренду'], false, 2367, 16, 3.0, 9.5, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: RERA index ~15.4', '2026-11-02'),
  ('palm-jumeirah', 'Palm Jumeirah', 'Палм-Джумейра', array['No metro: Palm Monorail along the trunk links to the tram and metro at Dubai Marina; water taxis','By car: JBR ~19 min, Dubai Mall ~24 min, DXB airport ~46 min','Beaches incl. Palm West Beach; Nakheel Mall, Golden Mile Galleria, Atlantis','Apartments on the trunk (Shoreline, Golden Mile), villas on the fronds'], array['Метро нет: монорельс вдоль ствола острова до трамвая и метро в Марине; водное такси','На машине: JBR ~19 мин, Dubai Mall ~24 мин, аэропорт DXB ~46 мин','Пляжи, в том числе Palm West Beach; Nakheel Mall, Golden Mile Galleria, Atlantis','Квартиры на «стволе» острова (Shoreline, Golden Mile), виллы на «ветвях»'], false, 3250, 18, 3.0, 7.5, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: standard 11–15, branded 20–30+; est. blend', '2026-11-02'),
  ('emaar-beachfront', 'Emaar Beachfront', 'Эмаар Бичфронт', array['Private beach between Dubai Marina and Palm','New Emaar towers','No metro station inside the community'], array['Частный пляж между Мариной и Палмой','Новые башни Emaar','Метро внутри района нет'], false, 3452, 27, -2.0, -5.3, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: 2026 guides range 22–32', '2026-11-02'),
  ('jlt', 'Jumeirah Lake Towers (JLT)', 'Джумейра Лейк Тауэрс (JLT)', array['Next to Dubai Marina at lower prices','Two Red Line metro stations','DMCC free zone offices in the community'], array['Рядом с Мариной, но дешевле','Две станции красной ветки метро','Офисы свободной зоны DMCC в районе'], true, 1515, 14, 3.0, 3.0, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: RERA index ~13.65', '2026-11-02'),
  ('the-greens', 'The Greens', 'Зе Гринс', array['Low-rise Emaar community with green spaces','Next to Dubai Internet City and Media City','Established tenant base'], array['Малоэтажный район Emaar с зеленью','Рядом Dubai Internet City и Media City','Устоявшийся спрос арендаторов'], false, 1806, 14, 3.0, 9.7, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: est. (2025 guide ~13)', '2026-11-02'),
  ('the-views', 'The Views', 'Зе Вьюз', array['Emaar towers overlooking Emirates Golf Club','Next to The Greens','Mid-to-upper segment'], array['Башни Emaar с видом на Emirates Golf Club','Рядом с The Greens','Средний и выше среднего сегмент'], false, 2207, 16, 3.0, 12.0, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: est.', '2026-11-02'),
  ('jvc', 'Jumeirah Village Circle (JVC)', 'Джумейра Вилладж Серкл (JVC)', array['No metro: nearest station Mall of the Emirates (Red Line), feeder bus J01','By car: Dubai Mall ~21 min, Dubai Marina ~20 min, DXB airport ~38 min','Schools: JSS International (1 km), Sunmarke (1.8 km); 14 nearby schools rated Very Good or Outstanding','Circle Mall with cinema, 33 landscaped parks, Miracle Garden 3.7 km'], array['Метро в районе нет: ближайшая станция Mall of the Emirates (красная ветка), автобус J01','На машине: Dubai Mall ~21 мин, Дубай Марина ~20 мин, аэропорт DXB ~38 мин','Школы: JSS International (1 км), Sunmarke (1,8 км); рядом 14 школ с рейтингом Very Good или Outstanding','Circle Mall с кинотеатром, 33 парка, Miracle Garden в 3,7 км'], false, 1313, 13, 3.0, 3.7, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: 2026 guides range 10–22', '2026-11-02'),
  ('arjan', 'Arjan', 'Арджан', array['Near Miracle Garden and Al Barsha South','Many new mid-market towers','Car-dependent: no metro station'], array['Рядом Miracle Garden и Al Barsha South','Много новых башен среднего сегмента','Нужен автомобиль: метро нет'], false, 1401, 15.7, 3.0, 8.6, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 15.67', '2026-11-02'),
  ('al-furjan', 'Al Furjan', 'Аль-Фурджан', array['Family community with apartments and townhouses','Al Furjan metro station (Route 2020)','Close to Expo City and Jebel Ali'], array['Семейный район: квартиры и таунхаусы','Станция метро Al Furjan (Route 2020)','Рядом Expo City и Джебель-Али'], true, 1289, 14, 1.0, 0.9, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 13.91', '2026-11-02'),
  ('dubai-hills', 'Dubai Hills Estate', 'Дубай Хиллс Эстейт', array['No metro station today: a car is needed','By car: Dubai Mall ~13 min, DXB airport ~18 min, Palm Jumeirah ~15 min, JBR ~19 min','Dubai Hills Mall, 18-hole championship golf course, Dubai Hills Park','Schools: GEMS International (0.9 km), GEMS Wellington Academy (1.1 km); 10 nearby schools rated Very Good or Outstanding'], array['Метро пока нет: нужен автомобиль','На машине: Dubai Mall ~13 мин, аэропорт DXB ~18 мин, Палм ~15 мин, JBR ~19 мин','Dubai Hills Mall, гольф-поле чемпионского уровня на 18 лунок, Dubai Hills Park','Школы: GEMS International (0,9 км), GEMS Wellington Academy (1,1 км); рядом 10 школ с рейтингом Very Good или Outstanding'], false, 2464, 18.5, 3.0, 3.2, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 18.53', '2026-11-02'),
  ('creek-harbour', 'Dubai Creek Harbour', 'Дубай Крик Харбор', array['Blue Line metro station under construction, completion scheduled for 2029','By car: Dubai Mall ~14 min, DXB airport ~17 min, Palm Jumeirah ~25 min','Creek Beach, Creek Island Central Park, Ras Al Khor flamingo sanctuary 3 km, Festival City Mall 2.4 km','Schools: Swiss International Scientific (2.2 km), Deira International (2.4 km, Outstanding)'], array['Станция синей ветки метро строится, открытие запланировано на 2029 год','На машине: Dubai Mall ~14 мин, аэропорт DXB ~17 мин, Палм ~25 мин','Пляж Creek Beach, парк Creek Island, заповедник фламинго Рас-аль-Хор в 3 км, Festival City Mall в 2,4 км','Школы: Swiss International Scientific (2,2 км), Deira International (2,4 км, Outstanding)'], false, 2470, 21, 3.0, 6.2, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 20.67', '2026-11-02'),
  ('sobha-hartland', 'Sobha Hartland', 'Собха Хартленд', array['Green community in Mohammed Bin Rashid City','Several international schools','Short drive to Downtown'], array['Зелёный район в Mohammed Bin Rashid City','Несколько международных школ','Недалеко от Даунтауна'], false, 2052, 18, -2.0, -2.0, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 17.36', '2026-11-02'),
  ('mbr-city', 'Mohammed Bin Rashid City (MBR) / Meydan', 'Mohammed Bin Rashid City (MBR) / Мейдан', array['Large master plan next to Meydan and Ras Al Khor','Crystal Lagoon projects','Car-dependent: no metro station'], array['Большой мастер-план рядом с Мейданом','Проекты с кристальной лагуной','Нужен автомобиль: метро нет'], false, 2024, 16, 3.0, 3.5, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: 2026 guides range 12–20; est.', '2026-11-02'),
  ('town-square', 'Town Square', 'Таун Сквер', array['Nshama community off Al Qudra Road','Parks and community retail','Car-dependent: no metro station'], array['Район Nshama у Al Qudra Road','Парки и торговля в районе','Нужен автомобиль: метро нет'], false, 1379, 15.4, 3.0, 6.7, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 15.42', '2026-11-02'),
  ('the-cities', 'Motor City / Sports City / Studio City', 'Motor City / Sports City / Studio City', array['Established Dubailand communities','High gross yields on entry-level stock','Car-dependent: no metro station'], array['Устоявшиеся районы Dubailand','Высокая валовая доходность у недорогих объектов','Нужен автомобиль: метро нет'], false, 1044, 15.7, 3.0, 25.0, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: Sports City DLD/Mollak 2026 median 15.75', '2026-11-02'),
  ('dubai-south', 'Dubai South', 'Дубай Саут', array['Next to Al Maktoum airport and Expo City','Lowest entry prices among new communities','Car-dependent: no metro station in the residential district'], array['Рядом аэропорт Аль-Мактум и Expo City','Один из самых низких порогов входа','Нужен автомобиль: в жилой части метро нет'], false, 1062, 17.2, 2.0, 2.2, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: DLD/Mollak 2026 median 17.13', '2026-11-02'),
  ('damac-hills', 'DAMAC Hills', 'ДАМАК Хиллс', array['Golf community on Al Qudra Road','Mix of apartments, townhouses and villas','Car-dependent: no metro station'], array['Гольф-район у Al Qudra Road','Квартиры, таунхаусы и виллы','Нужен автомобиль: метро нет'], false, 1385, 14, 3.0, 8.8, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: est.', '2026-11-02'),
  ('emaar-south', 'Emaar South', 'Эмаар Саут', array['Emaar community in Dubai South with a golf course','Close to Al Maktoum airport','Car-dependent: no metro station'], array['Район Emaar в Дубай Саут с гольф-полем','Рядом аэропорт Аль-Мактум','Нужен автомобиль: метро нет'], false, 1230, 12, 3.0, 9.5, 'Prices: Property Monitor (DLD secondary sales, 2026 YTD to Apr); rents: Property Monitor (DLD registered rents, 2026 YTD to Apr); service charge: est.', '2026-11-02'),
  ('dso', 'Dubai Silicon Oasis (DSO)', 'Дубай Силикон Оазис (DSO)', array['Tech free zone with residential towers','Among the highest gross yields in Dubai','Blue Line metro planned, not yet open'], array['Технологическая свободная зона с жилыми башнями','Одна из самых высоких валовых доходностей','Синяя ветка метро планируется, пока не открыта'], false, 1086, 12, 2.0, null, 'Prices: Bayut H1 2026 (asking); rents: Bayut Q3 2026 (asking): studio, 1BR; service charge: est.', '2026-11-02'),
  ('international-city', 'International City', 'Интернешнл Сити', array['Lowest entry prices in Dubai','Very high gross yields','Blue Line metro planned, not yet open'], array['Самый низкий порог входа в Дубае','Очень высокая валовая доходность','Синяя ветка метро планируется, пока не открыта'], false, 1055, 8, 2.0, null, 'Prices: Bayut price index Aug 2026 (asking); rents: Bayut H1 2026 (asking); service charge: est. (guides 6–8)', '2026-11-02')
